import { POWERCARE_LOGO_URL } from "@/lib/brand";
import { subscriptionInvoiceNumber } from "@/lib/subscriptionInvoiceExport";
import { subscriptionBillableAmount, subscriptionTotals, formatSubscriptionMoney } from "@/lib/subscriptionTax";

const esc = (value) => String(value ?? "—").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const date = (value, ar) => new Date(value || Date.now()).toLocaleDateString(ar ? "ar-SA" : "en-GB");

export function printSubscriptionInvoiceBundle(rows, ar) {
  const subscriptions = rows.filter((row) => row.status !== "no_subscription");
  const combined = subscriptionTotals(subscriptions.reduce((sum, row) => sum + subscriptionBillableAmount(row), 0));
  const totalMoney = (value) => formatSubscriptionMoney(value, "USD", ar);
  const invoices = subscriptions.map((row) => {
    const currency = row.currency || "USD";
    const totals = subscriptionTotals(subscriptionBillableAmount(row));
    const money = (value) => formatSubscriptionMoney(value, currency, ar);
    const cycle = row.billing === "yearly" ? (ar ? "سنوي" : "Yearly") : (ar ? "شهري" : "Monthly");
    return `<section class="invoice-page"><div class="glass"><header><img src="${POWERCARE_LOGO_URL}" alt="PowerCare"><div><p>POWERCARE <span>•</span> OFFICIAL INVOICE</p><h1>${ar ? "فاتورة اشتراك" : "Subscription invoice"}</h1></div><b>${esc(subscriptionInvoiceNumber(row))}</b></header><div class="customer"><div><small>${ar ? "العميل" : "Customer"}</small><strong>${esc(row.companyName || "—")}</strong><p>${esc(row.email || "—")}</p></div><div><small>${ar ? "تاريخ الإصدار" : "Issue date"}</small><strong>${esc(date(row.startedAt, ar))}</strong></div></div><div class="details"><div><small>${ar ? "الباقة" : "Plan"}</small><strong>${esc(row.plan || "—")}</strong></div><div><small>${ar ? "دورة الفوترة" : "Billing cycle"}</small><strong>${esc(cycle)}</strong></div><div><small>${ar ? "العملة" : "Currency"}</small><strong>${esc(currency)}</strong></div></div><div class="amounts"><div><small>${ar ? "قبل الضريبة" : "Subtotal"}</small><strong>${money(totals.subtotal)}</strong></div><div><small>${ar ? "ضريبة القيمة المضافة 15%" : "VAT 15%"}</small><strong>${money(totals.vat)}</strong></div><div class="total"><small>${ar ? "الإجمالي شامل الضريبة" : "Total including VAT"}</small><strong>${money(totals.total)}</strong></div></div><footer>PowerCare <span>•</span> ${ar ? "فاتورة إلكترونية موحدة" : "Unified electronic invoice"}</footer></div></section>`;
  }).join("");
  const html = `<!doctype html><html dir="${ar ? "rtl" : "ltr"}"><head><meta charset="utf-8"><title>${ar ? "جميع فواتير الاشتراكات" : "All subscription invoices"}</title><style>@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;background:#071c2a;color:#f8fafc;font-family:Tahoma,Arial,sans-serif;-webkit-print-color-adjust:exact;print-color-adjust:exact}.cover,.invoice-page{width:210mm;min-height:297mm;padding:18mm;background:radial-gradient(circle at 12% 8%,rgba(212,175,55,.22),transparent 30%),radial-gradient(circle at 90% 88%,rgba(86,164,196,.18),transparent 32%),linear-gradient(145deg,#0b2a3b,#04131f);page-break-after:always}.glass{min-height:261mm;padding:12mm;border:1px solid rgba(255,255,255,.2);border-radius:9mm;background:linear-gradient(145deg,rgba(255,255,255,.14),rgba(255,255,255,.045));box-shadow:0 12mm 30mm rgba(0,0,0,.28),inset 0 1px rgba(255,255,255,.18);backdrop-filter:blur(18px)}.cover .glass{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.cover img{width:34mm;height:34mm;object-fit:contain;filter:drop-shadow(0 5mm 9mm rgba(0,0,0,.3))}.cover h1{margin:8mm 0 2mm;font-size:28px}.cover p{color:rgba(248,250,252,.68)}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:3mm;width:100%;margin-top:12mm}.summary div,.details div,.amounts div{padding:5mm;border:1px solid rgba(255,255,255,.16);border-radius:5mm;background:linear-gradient(135deg,rgba(255,255,255,.12),rgba(255,255,255,.035));box-shadow:inset 0 1px rgba(255,255,255,.12)}small{display:block;margin-bottom:2mm;color:rgba(248,250,252,.62);font-size:8px}.summary strong{font-size:13px}.invoice-page:last-child{page-break-after:auto}header{display:flex;align-items:center;gap:5mm;padding-bottom:7mm;border-bottom:1px solid rgba(255,255,255,.16)}header img{width:18mm;height:18mm;object-fit:contain}header div{flex:1}header p{margin:0;font-size:9px;letter-spacing:.08em}header span,footer span,.total strong{color:#d4af37}header h1{margin:2mm 0 0;font-size:20px}header>b{padding:3mm 4mm;border:1px solid rgba(212,175,55,.5);border-radius:99px;color:#e5c65c;font:700 10px monospace}.customer{display:grid;grid-template-columns:2fr 1fr;gap:5mm;padding:10mm 0}.customer>div{padding:5mm;border-radius:5mm;background:rgba(255,255,255,.06)}.customer strong{font-size:15px}.customer p{margin:2mm 0 0;color:rgba(248,250,252,.68);font-size:9px}.details{display:grid;grid-template-columns:repeat(3,1fr);gap:4mm}.details strong{font-size:11px}.amounts{display:grid;grid-template-columns:repeat(3,1fr);gap:4mm;margin-top:8mm}.amounts strong{font-size:15px}.amounts .total{border-color:rgba(212,175,55,.48);background:linear-gradient(135deg,rgba(212,175,55,.17),rgba(255,255,255,.05))}.amounts .total strong{font-size:18px}footer{margin-top:12mm;text-align:center;color:rgba(248,250,252,.58);font-size:8px}</style></head><body><section class="cover"><div class="glass"><img src="${POWERCARE_LOGO_URL}" alt="PowerCare"><h1>${ar ? "كتاب فواتير الاشتراكات" : "Subscription invoice book"}</h1><p>${ar ? "ملف موحد لجميع الاشتراكات" : "One unified file for all subscriptions"} • ${date(Date.now(), ar)}</p><div class="summary"><div><small>${ar ? "عدد الاشتراكات" : "Subscriptions"}</small><strong>${subscriptions.length}</strong></div><div><small>${ar ? "قبل الضريبة" : "Subtotal"}</small><strong>${totalMoney(combined.subtotal)}</strong></div><div><small>${ar ? "الضريبة 15%" : "VAT 15%"}</small><strong>${totalMoney(combined.vat)}</strong></div><div><small>${ar ? "الإجمالي" : "Total"}</small><strong>${totalMoney(combined.total)}</strong></div></div></div></section>${invoices}<script>onload=()=>setTimeout(()=>print(),500)</script></body></html>`;
  const win = window.open("", "_blank");
  if (!win) return;
  win.document.write(html);
  win.document.close();
}